public class Pizza
{

   String belag;
   double preis;
   int durchmesser = 23;

   public Pizza(String belagNeu)
   {
      belag = belagNeu;

      if(belag == "Tomaten, Käse")
      {
         preis = 6.50;
      } else {
         preis = 7.50;
      }
   }

   public void belegen()
   {
      println("Pizza wird mit " + belag + " belegt!");
   }

   public double flaecheBerechnen()
   {
      return(3.14 * durchmesser / 2 * durchmesser / 2);
   }
}
